// Achievement badge catalog. Pure metadata: the awarding engine maps badge ids
// to counter queries in code, and the artwork lives at public/badges/<id>.svg
// (tier and locked variants are generated by scripts/generate-badge-variants.mjs).

export type BadgeCategory = 'drep' | 'spo' | 'cc' | 'proposer' | 'forum' | 'crossover';

export interface Badge {
  /** Stable id; equals the artwork filename public/badges/<id>.svg. */
  id: string;
  name: string;
  /** Plain-language criterion shown on /badges and in galleries. */
  description: string;
  category: BadgeCategory;
  /** Hidden badges render as the mystery card until earned. */
  hidden?: boolean;
  /** Bronze / silver / gold thresholds; absent for single-award badges. */
  tiers?: [number, number, number];
  /** Progress goal of a single-award badge when it is more than 1. */
  goal?: number;
}

// Indexed by the badge_awards.tier value: 0 = untiered single award, 1..3 = bronze/silver/gold.
export const TIER_SLUGS = ['', 'bronze', 'silver', 'gold'] as const;

