const BADGES_BY_ID = new Map(BADGES.map((b) => [b.id, b]));

export function getBadge(id: string): Badge | undefined {
  return BADGES_BY_ID.get(id);
}

export const VISIBLE_BADGES: readonly Badge[] = BADGES.filter((b) => !b.hidden);
export const HIDDEN_BADGES: readonly Badge[] = BADGES.filter((b) => b.hidden);

/** Artwork URL for a badge at a given award tier (0 or absent = the base file). */
export function badgeImagePath(id: string, tier = 0): string {
  const slug = TIER_SLUGS[tier] ?? '';
  return slug ? `/badges/${id}-${slug}.svg` : `/badges/${id}.svg`;
}

/** Artwork URL for a not-yet-earned badge (mystery card when hidden). */
export function badgeLockedImagePath(badge: Badge): string {
  return badge.hidden ? '/badges/mystery.svg' : `/badges/${badge.id}-locked.svg`;
}
